package app.manga.manga;
import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class JikanProviderTest{@Test void nullableFieldsMapWithoutInventingChapters()throws Exception{var n=new ObjectMapper().readTree("{\"mal_id\":7,\"title\":\"A title\",\"score\":0,\"chapters\":null,\"images\":{\"jpg\":{}},\"authors\":[],\"genres\":[]}");var m=JikanProvider.map(n);assertEquals(7,m.id());assertEquals("A title",m.title());assertNull(m.score());assertNull(m.chapters());assertNull(m.imageUrl());assertTrue(m.genres().isEmpty());} @Test void usesEnglishAndJapaneseTitlesWhenPresent()throws Exception{var n=new ObjectMapper().readTree("{\"mal_id\":8,\"title\":\"題名\",\"titles\":[{\"type\":\"English\",\"title\":\"Title\"},{\"type\":\"Japanese\",\"title\":\"題名\"}]}");var m=JikanProvider.map(n);assertEquals("Title",m.titleEnglish());assertEquals("題名",m.titleJapanese());}}
